@namespace sv_0b0bebab6a2f4700860375cb497afb23.Components.Pages.Apply

<nav class="mb-4">
    <ol class="list-group list-group-horizontal text-center">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var isCompleted = step < CurrentStep;
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep;

            <li class="list-group-item flex-fill p-2 @(isCurrent ? "list-group-item-primary fw-bold" : "") @(isFuture ? "text-muted" : "")"
                style="@(isCompleted ? "cursor:pointer;" : "")"
                @onclick="() => OnStepClicked(step)">
                @if (isCompleted)
                {
                    <span class="me-1">&#10003;</span>
                }
                <span>@StepNames[step]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnNavigate { get; set; }

    private async Task OnStepClicked(int step)
    {
        if (step < CurrentStep)
        {
            await OnNavigate.InvokeAsync(step);
        }
    }
}

