@page "/apply"
@rendermode InteractiveServer
@using sv_0b0bebab6a2f4700860375cb497afb23.Components.Pages.Apply
@using sv_0b0bebab6a2f4700860375cb497afb23.Models
@using static WorkHistoryStep
@using static ReferencesStep
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnNavigate="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                @bind-FullName="fullName"
                @bind-Email="email"
                @bind-Phone="phone"
                @bind-Address="address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="NextStep" />
            break;

        case 1:
            <WorkHistoryStep
                @bind-Entries="workEntries"
                OnNext="NextStep"
                OnBack="PreviousStep" />
            break;

        case 2:
            <ReferencesStep
                @bind-References="references"
                OnNext="NextStep"
                OnBack="PreviousStep" />
            break;

        case 3:
            <CoverLetterStep
                @bind-CoverLetter="coverLetter"
                OnNext="NextStep"
                OnBack="PreviousStep" />
            break;

        case 4:
            <ReviewStep
                FullName="@fullName"
                Email="@email"
                Phone="@phone"
                Address="@address"
                WorkEntries="@workEntries"
                References="@references"
                CoverLetter="@coverLetter"
                OnEdit="GoToStep"
                OnBack="PreviousStep"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;

    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void GoToStep(int step) => currentStep = step;

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(fullName, email, phone, address),
            new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
            references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

