@namespace sv_0b0bebab6a2f4700860375cb497afb23.Components.Pages.Apply

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row mb-2">
                <div class="col-md-6">
                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                    <input class="form-control" value="@entry.Company"
                           @onchange="e => SetCompany(index, e)" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input class="form-control" value="@entry.Title"
                           @onchange="e => SetTitle(index, e)" />
                </div>
            </div>

            <div class="row mb-2">
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" value="@entry.StartDate.ToString("yyyy-MM-dd")"
                           @onchange="e => SetStartDate(index, e)" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control"
                           value="@(entry.EndDate?.ToString("yyyy-MM-dd"))"
                           disabled="@entry.IsCurrent"
                           @onchange="e => SetEndDate(index, e)" />
                </div>
                <div class="col-md-4 d-flex align-items-end mb-1">
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"current-{index}")"
                               checked="@entry.IsCurrent"
                               @onchange="e => SetIsCurrent(index, e)" />
                        <label class="form-check-label" for="@($"current-{index}")">Currently working here</label>
                    </div>
                </div>
            </div>

            <div class="mb-2">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="2" value="@entry.Description"
                          @onchange="e => SetDescription(index, e)"></textarea>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (ValidationMessage is not null)
{
    <div class="alert alert-danger">@ValidationMessage</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = [];
    [Parameter] public EventCallback<List<WorkEntryModel>> EntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationMessage;

    private void SetCompany(int i, ChangeEventArgs e) { Entries[i].Company = (string?)e.Value ?? ""; Notify(); }
    private void SetTitle(int i, ChangeEventArgs e) { Entries[i].Title = (string?)e.Value ?? ""; Notify(); }
    private void SetDescription(int i, ChangeEventArgs e) { Entries[i].Description = (string?)e.Value ?? ""; Notify(); }

    private void SetStartDate(int i, ChangeEventArgs e)
    {
        if (DateTime.TryParse((string?)e.Value, out var d)) Entries[i].StartDate = d;
        Notify();
    }

    private void SetEndDate(int i, ChangeEventArgs e)
    {
        Entries[i].EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null;
        Notify();
    }

    private void SetIsCurrent(int i, ChangeEventArgs e)
    {
        var val = (bool)(e.Value ?? false);
        Entries[i].IsCurrent = val;
        if (val) Entries[i].EndDate = null;
        Notify();
    }

    private void Notify() => EntriesChanged.InvokeAsync(Entries);

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        Notify();
    }

    private void RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
        Notify();
    }

    private async Task HandleNext()
    {
        ValidationMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == default)
            {
                ValidationMessage = "Each position requires a company name, job title, and start date.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

